INSERT INTO `Users` (`id`, `username`, `email`, `password`, `role`, `bio`, `avatarUrl`, `location`, `specialty`, `websiteUrl`, `isBanned`, `bannedReason`, `canReport`, `reportBlockedReason`, `createdAt`, `updatedAt`) VALUES
  (1, 'Recipe_web', 'Recipe@web.com', '$2b$10$5E.akxBhAcHAACsaTsYVueiJt/Cw.lbQe60zTFNsKryQ0JJBapd/e', 'admin', 'Founder and administrator of Ef''Recipe. I built this community cookbook so home cooks and professionals could share recipes, videos and tips in one friendly place. I look after the platform, the subscriptions and the partner ads, and I read every ticket that lands in the admin inbox.', 'https://api.dicebear.com/9.x/avataaars/png?size=400&seed=Recipe_web', 'Paris, France', 'Platform Administration', 'https://efrecipe.example.com', FALSE, NULL, TRUE, NULL, '2025-03-03 09:00:00', '2025-03-03 09:00:00'),
  (2, 'Cyp', 'cyprien.donne@efrei.net', '$2b$10$EvbYAIXN1kTNeBC0CG0pTuy/R2O5iG3ChF3Cow2gB57HXGPpZoVni', 'moderator', 'Community moderator since the early days. I review reports, keep the lounge welcoming and make sure every recipe stays credited to its chef. Off duty I experiment with weeknight pasta and spicy one-pot dinners.', 'https://api.dicebear.com/9.x/avataaars/png?size=400&seed=Cyp', 'Paris, France', 'Community Moderation & Quick Dinners', NULL, FALSE, NULL, TRUE, NULL, '2025-03-17 10:30:00', '2025-03-17 10:30:00'),
  (3, 'Lili', 'lili-rose.lauret@efrei.net', '$2b$10$x7G/GbvawKu0LsCQfznOFu3DcSnSGx0f/v18iPeCtpJnnPB79sPnS', 'moderator', 'Moderator and baking fan. I handle billing questions and creator support, and I am usually the first to try the new dessert recipes. If you have a question about a payment or a subscription, open a ticket and I will get back to you.', 'https://api.dicebear.com/9.x/avataaars/png?size=400&seed=Lili', 'Paris, France', 'Billing Support & Desserts', NULL, FALSE, NULL, TRUE, NULL, '2025-06-09 14:15:00', '2025-06-09 14:15:00'),
  (4, 'rayoogo', 'raphael.perricaud@efrei.net', '$2b$10$0JTvEhIObLAlDHLuFxX6e.CzvlLZq6uLVPCp2LTPqu1oSeUOKqENa', 'moderator', 'Moderator and technical troubleshooter. I follow bug reports, video playback issues and anything that does not load the way it should. When the laptop is closed I am at the grill, and I will happily talk about sauces for hours.', 'https://api.dicebear.com/9.x/avataaars/png?size=400&seed=rayoogo', 'Paris, France', 'Technical Support & Grill', NULL, FALSE, NULL, TRUE, NULL, '2025-09-15 11:40:00', '2025-09-15 11:40:00'),
  (5, 'Lucas_Moreau', 'lucas.moreau@example.com', '$2b$10$J1CSCmM9W0QfmHw4uVYaKes2JcdR0FPslj2p5r.ohLGkniTWkI5zK', 'user', 'Pastry chef trained in Lyon, now sharing bistro classics and patisserie tricks from my small home kitchen. I love filming step-by-step video masterclasses, because the right caramel colour is easier to see than to describe. Ask me anything about tarts, sauces and French technique.', 'https://api.dicebear.com/9.x/avataaars/png?size=400&seed=Lucas_Moreau', 'Lyon, France', 'French Pastry & Bistro', 'https://lucasmoreau.example.com', FALSE, NULL, TRUE, NULL, '2025-04-02 08:30:00', '2025-04-02 08:30:00'),
  (6, 'Marco_Bellini', 'marco.bellini@example.com', '$2b$10$J1CSCmM9W0QfmHw4uVYaKes2JcdR0FPslj2p5r.ohLGkniTWkI5zK', 'user', 'Born in Bologna and raised on my nonna''s tagliatelle. I cook with few ingredients and strong opinions: no cream in carbonara, ever! I film my dough-making sessions and accept paid requests for custom pasta recipes.', 'https://api.dicebear.com/9.x/avataaars/png?size=400&seed=Marco_Bellini', 'Bologna, Italy', 'Handmade Pasta & Risotto', NULL, FALSE, NULL, TRUE, NULL, '2025-04-19 17:10:00', '2025-04-19 17:10:00'),
  (7, 'Awa_Diallo', 'awa.diallo@example.com', '$2b$10$J1CSCmM9W0QfmHw4uVYaKes2JcdR0FPslj2p5r.ohLGkniTWkI5zK', 'user', 'West African spices and comforting family dishes, the way they were cooked in my grandmother''s courtyard in Dakar. I mix tradition with fusion ideas and love explaining where each spice comes from. Yassa and thieboudienne are my signature dishes.', 'https://api.dicebear.com/9.x/avataaars/png?size=400&seed=Awa_Diallo', 'Dakar, Senegal', 'West African & Fusion', NULL, FALSE, NULL, TRUE, NULL, '2025-05-27 12:00:00', '2025-05-27 12:00:00'),
  (8, 'Tom_Carter', 'tom.carter@example.com', '$2b$10$J1CSCmM9W0QfmHw4uVYaKes2JcdR0FPslj2p5r.ohLGkniTWkI5zK', 'user', 'Quick weeknight meals, burgers and backyard barbecue from Austin. I believe good comfort food does not need to be complicated, just seasoned properly and cooked with patience. Brisket is my long-term project.', 'https://api.dicebear.com/9.x/avataaars/png?size=400&seed=Tom_Carter', 'Austin, USA', 'Grill & Comfort Food', NULL, FALSE, NULL, TRUE, NULL, '2025-06-14 19:45:00', '2025-06-14 19:45:00'),
  (9, 'Pierre_Fabre', 'pierre.fabre@example.com', '$2b$10$J1CSCmM9W0QfmHw4uVYaKes2JcdR0FPslj2p5r.ohLGkniTWkI5zK', 'user', 'Traditional Mediterranean and Provençal home cooking, with a soft spot for fresh seafood from the Marseille port. I cook with the seasons and share the small habits that make a ratatouille taste like summer.', 'https://api.dicebear.com/9.x/avataaars/png?size=400&seed=Pierre_Fabre', 'Marseille, France', 'Provençal & Seafood', NULL, FALSE, NULL, TRUE, NULL, '2025-07-08 10:20:00', '2025-07-08 10:20:00'),
  (10, 'Julie_Lambert', 'julie.lambert@example.com', '$2b$10$J1CSCmM9W0QfmHw4uVYaKes2JcdR0FPslj2p5r.ohLGkniTWkI5zK', 'user', 'Sweet treats, Sunday brunch pancakes and everything chocolate. I started baking at fifteen and never stopped. I run a small bakery blog and take paid requests for beginner-friendly dessert recipes with a video.', 'https://api.dicebear.com/9.x/avataaars/png?size=400&seed=Julie_Lambert', 'Paris, France', 'Baking & Desserts', 'https://julielambert.example.com', FALSE, NULL, TRUE, NULL, '2025-08-12 15:05:00', '2025-08-12 15:05:00'),
  (11, 'Nina_Tremblay', 'nina.tremblay@example.com', '$2b$10$J1CSCmM9W0QfmHw4uVYaKes2JcdR0FPslj2p5r.ohLGkniTWkI5zK', 'user', 'Colourful, fresh and plant-forward recipes in under twenty minutes. I cook for a busy household in Montreal and focus on dishes that make vegetables the star of the plate.', 'https://api.dicebear.com/9.x/avataaars/png?size=400&seed=Nina_Tremblay', 'Montreal, Canada', 'Vegetarian & Fresh', NULL, FALSE, NULL, TRUE, NULL, '2025-09-23 09:50:00', '2025-09-23 09:50:00'),
  (12, 'Sophie_Dubois', 'sophie.dubois@example.com', '$2b$10$J1CSCmM9W0QfmHw4uVYaKes2JcdR0FPslj2p5r.ohLGkniTWkI5zK', 'user', 'Home cook from Brussels testing recipes from around the world and leaving honest reviews. I am a Gourmet Plus subscriber because I never miss a video tutorial, and I like asking chefs for custom recipes.', 'https://api.dicebear.com/9.x/avataaars/png?size=400&seed=Sophie_Dubois', 'Brussels, Belgium', 'Home Cooking', NULL, FALSE, NULL, TRUE, NULL, '2025-10-30 20:15:00', '2025-10-30 20:15:00'),
  (13, 'Thando_Nkosi', 'thando.nkosi@example.com', '$2b$10$J1CSCmM9W0QfmHw4uVYaKes2JcdR0FPslj2p5r.ohLGkniTWkI5zK', 'user', 'Braai master in the making from Cape Town. I love street food, spicy sauces and Sunday cookouts with the whole family. I am still learning how to give feedback kindly, and I am working on it.', 'https://api.dicebear.com/9.x/avataaars/png?size=400&seed=Thando_Nkosi', 'Cape Town, South Africa', 'Braai & Street Food', NULL, FALSE, NULL, FALSE, 'Three unfounded copyright reports in nine days (28 April to 6 May 2026). The restriction can be reviewed from 6 February 2027 through a support ticket.', '2025-12-04 18:30:00', '2026-05-06 11:05:00'),
  (14, 'Kyle_Jacobs', 'kyle.jacobs@example.com', '$2b$10$J1CSCmM9W0QfmHw4uVYaKes2JcdR0FPslj2p5r.ohLGkniTWkI5zK', 'user', 'Kitchen gadget collector from Durban. Air fryers, knives, blenders: if it plugs in, I have probably tested it.', 'https://api.dicebear.com/9.x/avataaars/png?size=400&seed=Kyle_Jacobs', 'Durban, South Africa', 'Kitchen Gadgets', NULL, TRUE, 'Repeated promotional spam in the community chat after a warning (1 March and 4 March 2026).', TRUE, NULL, '2026-02-14 13:25:00', '2026-03-04 09:50:00'),
  (15, 'Zoe_Petersen', 'zoe.petersen@example.com', '$2b$10$J1CSCmM9W0QfmHw4uVYaKes2JcdR0FPslj2p5r.ohLGkniTWkI5zK', 'user', 'Complete beginner from Stellenbosch learning to bake one recipe at a time. My first banana bread sank in the middle, so I now read every step twice. Follow along for my progress, and my failures.', 'https://api.dicebear.com/9.x/avataaars/png?size=400&seed=Zoe_Petersen', 'Stellenbosch, South Africa', 'Beginner Baking', NULL, FALSE, NULL, TRUE, NULL, '2026-05-06 16:40:00', '2026-11-10 08:00:00'),
  (16, 'test', 'mpho.khumalo@example.com', '$2b$10$AM8LgfN2KjlzwcDovPZUCOWy987tfcd8EJwFn2qI19QkgSkSzJUbG', 'user', 'Home entertainer from Johannesburg. Weekends mean friends, a braai and a long table, so I am always looking for crowd-pleasing recipes that scale up easily. I also run a small braai accessories shop.', 'https://api.dicebear.com/9.x/avataaars/png?size=400&seed=Mpho_Khumalo', 'Johannesburg, South Africa', 'Braai & Home Entertaining', NULL, FALSE, NULL, TRUE, NULL, '2026-06-20 11:10:00', '2026-06-20 11:10:00');
INSERT INTO `Recipes` (`id`, `title`, `ingredients`, `instructions`, `prepTime`, `category`, `imageUrl`, `videoUrl`, `isVideoPremium`, `videoUnlockPrice`, `sharedAt`, `createdAt`, `updatedAt`, `userId`) VALUES
  (1, 'Traditional Tarte Tatin', '6 apples\n150 g sugar\n80 g butter\n1 puff pastry sheet', 'Peel the golden apples and cut them into large wedges.\nMake an amber caramel in a tatin pan with the butter and sugar.\nArrange the apples neatly on top of the caramel.\nCover with the puff pastry and tuck in the edges.\nBake for 35 minutes at 180°C (350°F), then unmold while still warm.', 45, 'Dessert', 'https://images.unsplash.com/photo-1568571780765-9276ac8b75a2?auto=format&fit=crop&w=800&q=80', 'https://www.youtube.com/watch?v=Al7W2wpNyb4&pp=ygUXVHJhZGl0aW9uYWwgVGFydGUgVGF0aW4%3D', TRUE, 2.99, '2025-04-26 09:14:00', '2025-04-26 09:14:00', '2025-04-26 09:14:00', 5),
  (2, 'Authentic Pasta Carbonara', '400 g spaghetti\n150 g guanciale\n4 egg yolks\n100 g pecorino romano\nBlack pepper (to taste)', 'Fry the guanciale until crisp.\nCook the pasta al dente.\nMix the egg yolks with the pecorino and plenty of black pepper.\nToss the pasta off the heat with the guanciale fat and the egg sauce, adding a ladle of pasta water.', 15, 'Plat', 'https://images.unsplash.com/photo-1612874742237-6526221588e3?auto=format&fit=crop&w=800&q=80', 'https://www.youtube.com/watch?v=3AAdKl1UYZs&pp=ygUZQXV0aGVudGljIFBhc3RhIENhcmJvbmFyYQ%3D%3D', TRUE, 2.49, '2025-05-11 17:32:00', '2025-05-11 17:32:00', '2025-05-11 17:32:00', 6),
  (3, 'Senegalese Chicken Yassa', '1 whole chicken\n6 onions\n4 limes\n3 garlic cloves\n2 tbsp dijon mustard\n1 chili pepper\n300 g white rice', 'Cut the chicken into pieces.\nMarinate the chicken and the sliced onions in the lime juice, mustard, garlic and chili for 2 hours.\nGrill the chicken in the oven or on the barbecue.\nSlowly cook the onions in a pan, then add the chicken back in.\nServe piping hot with white rice.', 60, 'Plat', 'https://images.unsplash.com/photo-1598515214211-89d3c73ae83b?auto=format&fit=crop&w=800&q=80', 'https://www.youtube.com/watch?v=yT1mdPyiqdo&pp=ygUYU2VuZWdhbGVzZSBDaGlja2VuIFlhc3Nh', TRUE, 3.49, '2025-06-15 12:05:00', '2025-06-15 12:05:00', '2025-06-15 12:05:00', 7),
  (4, 'Grilled Chicken Caesar Salad', '1 romaine lettuce\n2 chicken breasts\n80 g croutons\n50 g parmesan\n4 anchovy fillets\n3 tbsp mayonnaise\n1 lemons', 'Make the dressing: mash the anchovies and mix them with the mayonnaise and the lemon juice.\nGrill the chicken breasts, then slice them.\nWash and chop the lettuce.\nAssemble the salad with the croutons, chicken and shaved parmesan.\nDrizzle generously with the Caesar dressing.', 20, 'Entrée', 'https://images.unsplash.com/photo-1550304943-4f24f54ddde9?auto=format&fit=crop&w=800&q=80', 'https://www.youtube.com/watch?v=sSxx64Ku-5c&pp=ygUcR3JpbGxlZCBDaGlja2VuIENhZXNhciBTYWxhZA%3D%3D', TRUE, NULL, '2025-09-14 11:20:00', '2025-09-14 11:20:00', '2025-09-14 11:20:00', 5),
  (5, 'Classic French Omelette', '3 eggs\n15 g butter\nSalt (to taste)\nBlack pepper (to taste)', 'Beat the eggs with a pinch of salt and pepper.\nMelt the butter in a non-stick pan over medium heat.\nPour in the eggs and stir gently while they set.\nFold the omelette in three and slide it onto a plate.', 10, 'Plat', 'https://plus.unsplash.com/premium_photo-1667807521536-bc35c8d8b64b?q=80&w=1170&auto=format&fit=crop&ixlib=rb-4.1.0&ixid=NHwxMjA3fDA%3D', 'https://www.youtube.com/watch?v=_Wb5Crj917I&pp=ygUXQ2xhc3NpYyBGcmVuY2ggT21lbGV0dGU%3D', TRUE, NULL, '2025-12-28 07:45:00', '2025-12-28 07:45:00', '2025-12-28 07:45:00', 8),
  (6, 'Garlic Butter Shrimp', '300 g shrimp\n40 g butter\n4 garlic cloves\n1 lemons\n10 g fresh parsley\nSalt (to taste)', 'Melt the butter in a large skillet over medium heat.\nAdd the minced garlic and cook for 30 seconds.\nAdd the shrimp and cook 2 to 3 minutes per side until pink.\nSqueeze the lemon over the shrimp and season with salt.\nSprinkle with chopped parsley and serve immediately.', 15, 'Plat', 'https://images.unsplash.com/photo-1625943553852-781c6dd46faa?q=80&w=1045&auto=format&fit=crop&ixlib=rb-4.1.0&ixid=NHwxMjA3fDA%3D', 'https://www.youtube.com/watch?v=JS12i22tk7A&pp=ygUUR2FybGljIEJ1dHRlciBTaHJpbXA%3D', TRUE, NULL, '2026-04-26 19:10:00', '2026-04-26 19:10:00', '2026-04-26 19:10:00', 9),
  (7, 'Tomato Basil Bruschetta', '1 baguette\n4 tomatoes\n2 garlic cloves\n10 g fresh basil\n3 tbsp olive oil\nSalt (to taste)', 'Dice the tomatoes and mix them with the chopped basil, olive oil and salt.\nSlice the baguette and toast the slices.\nRub each warm slice with a garlic clove.\nTop with the tomato mixture and serve right away.', 15, 'Entrée', 'https://images.unsplash.com/photo-1630230596557-ad07b433f5c0?q=80&w=1170&auto=format&fit=crop&ixlib=rb-4.1.0&ixid=NHwxMjA3fDA%3D', 'https://www.youtube.com/watch?v=Q3xg35pcLyo&t=89s&pp=ygUXVG9tYXRvIEJhc2lsIEJydXNjaGV0dGE%3D', TRUE, NULL, '2025-06-21 13:00:00', '2025-06-21 13:00:00', '2025-06-21 13:00:00', 6),
  (8, 'French Onion Soup', '6 onions\n50 g butter\n1000 ml beef broth\n4 bread slices\n150 g gruyere\nBlack pepper (to taste)', 'Slice the onions thinly.\nCook them in the butter over low heat for about 40 minutes until deep golden.\nAdd the beef broth and simmer for 15 minutes.\nLadle into oven-safe bowls and top with the bread and grated gruyere.\nGrill until the cheese is bubbling and golden.', 60, 'Entrée', 'https://images.unsplash.com/photo-1549203438-a7696aed4dac?w=1000&auto=format&fit=crop&q=60&ixlib=rb-4.1.0&ixid=NHwxMjA3fDA%3D', 'https://www.youtube.com/watch?v=cYY6mBu-UQ0&pp=ygURRnJlbmNoIE9uaW9uIFNvdXA%3D', TRUE, 1.99, '2025-11-23 18:25:00', '2025-11-23 18:25:00', '2025-11-23 18:25:00', 9),
  (9, 'Fluffy Pancakes', '250 g flour\n500 ml milk\n3 eggs\n2 tbsp sugar\n30 g butter\nSalt (to taste)', 'Whisk the flour, sugar and a pinch of salt in a large bowl.\nAdd the eggs, then pour in the milk little by little to get a smooth batter.\nStir in the melted butter and let the batter rest for 10 minutes.\nCook ladles of batter in a hot pan, about 2 minutes per side.', 15, 'Plat', 'https://plus.unsplash.com/premium_photo-1663854478296-dd00b6257021?w=1000&auto=format&fit=crop&q=60&ixlib=rb-4.1.0&ixid=NHwxMjA3fDA%3D', 'https://www.youtube.com/watch?v=9zCVCL4V8JQ&pp=ygUPRmx1ZmZ5IFBhbmNha2Vz', TRUE, NULL, '2026-01-11 08:30:00', '2026-01-11 08:30:00', '2026-01-11 08:30:00', 10),
  (10, 'Dark Chocolate Mousse', '200 g dark chocolate\n4 eggs\n30 g sugar\nSalt (to taste)', 'Melt the chocolate in a bain-marie and let it cool slightly.\nSeparate the eggs and stir the yolks into the chocolate.\nWhisk the whites with a pinch of salt into stiff peaks, adding the sugar at the end.\nFold the whites into the chocolate gently, in two batches.\nChill for at least 3 hours before serving.', 30, 'Dessert', 'https://images.unsplash.com/photo-1603032305813-be7441bc1037?w=1000&auto=format&fit=crop&q=60&ixlib=rb-4.1.0&ixid=NHwxMjA3fDA%3D', 'https://www.youtube.com/watch?v=YO74CgACqEY&pp=ygUVRGFyayBDaG9jb2xhdGUgTW91c3Nl0gcJCcgHAYcqIYzv', TRUE, 2.49, '2025-09-02 20:15:00', '2025-09-02 20:15:00', '2025-09-02 20:15:00', 10),
  (11, 'Spaghetti Bolognese', '400 g spaghetti\n500 g ground beef\n1 onions\n2 carrots\n2 garlic cloves\n400 g canned tomatoes\n2 tbsp tomato paste\n2 tbsp olive oil\nSalt (to taste)\nBlack pepper (to taste)', 'Finely chop the onion, carrots and garlic.\nSoften them in the olive oil, then add the ground beef and brown it.\nStir in the tomato paste and the canned tomatoes, then season.\nSimmer gently for 1 hour, stirring from time to time.\nCook the spaghetti al dente and serve with the sauce.', 90, 'Plat', 'https://images.unsplash.com/photo-1622973536968-3ead9e780960?q=80&w=1170&auto=format&fit=crop&ixlib=rb-4.1.0&ixid=NHwxMjA3fDA%3D', 'https://www.youtube.com/watch?v=v2WqcHH65NQ&pp=ygUTU3BhZ2hldHRpIEJvbG9nbmVzZdIHCQnIBwGHKiGM7w%3D%3D', TRUE, NULL, '2025-10-05 12:40:00', '2025-10-05 12:40:00', '2025-10-05 12:40:00', 6),
  (12, 'Colorful Vegetable Stir-Fry', '2 bell peppers\n2 carrots\n200 g broccoli\n3 tbsp soy sauce\n2 garlic cloves\n1 tbsp vegetable oil\n200 g white rice', 'Cook the rice according to the package instructions.\nCut the peppers, carrots and broccoli into bite-size pieces.\nHeat the oil in a wok and fry the garlic for 30 seconds.\nAdd the vegetables and stir-fry over high heat for 6 to 8 minutes.\nPour in the soy sauce, toss and serve over the rice.', 18, 'Plat', 'https://plus.unsplash.com/premium_photo-1705609329676-8585fbd02163?q=80&w=1172&auto=format&fit=crop&ixlib=rb-4.1.0&ixid=NHwxMjA3fDA%3D', 'https://www.youtube.com/watch?v=xgVQ8WHkaR0&pp=ygUbQ29sb3JmdWwgVmVnZXRhYmxlIFN0aXItRnJ5', TRUE, NULL, '2026-02-22 18:50:00', '2026-02-22 18:50:00', '2026-02-22 18:50:00', 11),
  (13, 'Creamy Chicken Curry', '3 chicken breasts\n1 onions\n3 garlic cloves\n400 ml coconut milk\n2 tbsp curry powder\n200 g canned tomatoes\n1 tbsp vegetable oil\n300 g white rice\nSalt (to taste)', 'Cut the chicken into cubes.\nCook the chopped onion and garlic in the oil until soft.\nAdd the chicken and the curry powder and brown for 5 minutes.\nPour in the tomatoes and the coconut milk and simmer for 25 minutes.\nSeason with salt and serve with the rice.', 45, 'Plat', 'https://plus.unsplash.com/premium_photo-1719908121468-eb177d387b10?w=1000&auto=format&fit=crop&q=60&ixlib=rb-4.1.0&ixid=NHwxMjA3fDA%3D', 'https://www.youtube.com/watch?v=gXpiGKf7ixA&pp=ygUUQ3JlYW15IENoaWNrZW4gQ3Vycnk%3D', TRUE, NULL, '2025-11-09 19:30:00', '2025-11-09 19:30:00', '2025-11-09 19:30:00', 7),
  (14, 'Homemade Cheeseburger', '500 g ground beef\n4 burger buns\n4 cheddar slices\n1 tomatoes\n4 lettuce leaves\n1 onions\nSalt (to taste)\nBlack pepper (to taste)', 'Shape the beef into 4 patties and season them with salt and pepper.\nGrill the patties for 3 to 4 minutes per side.\nAdd a slice of cheddar on each patty during the last minute.\nToast the buns and slice the tomato and onion.\nAssemble the burgers with the lettuce, tomato, onion and patty.', 30, 'Plat', 'https://images.unsplash.com/photo-1667329829058-ac191ba4a905?q=80&w=687&auto=format&fit=crop&ixlib=rb-4.1.0&ixid=NHwxMjA3fDA%3D', 'https://www.youtube.com/watch?v=BIG1h2vG-Qg&pp=ygUVSG9tZW1hZGUgQ2hlZXNlYnVyZ2Vy', TRUE, NULL, '2025-07-06 12:10:00', '2025-07-06 12:10:00', '2025-07-06 12:10:00', 8),
  (15, 'Margherita Pizza', '300 g flour\n190 ml water\n7 g dry yeast\nSalt (to taste)\n200 g canned tomatoes\n125 g mozzarella\n10 g fresh basil\n2 tbsp olive oil', 'Mix the flour, yeast, a pinch of salt and the water, then knead for 10 minutes.\nLet the dough rise for 1 hour in a warm place.\nCrush the tomatoes with a little salt and olive oil.\nRoll out the dough, spread the tomato sauce and add the torn mozzarella.\nBake at the highest temperature of your oven for 8 to 10 minutes.\nFinish with fresh basil leaves.', 40, 'Plat', 'https://plus.unsplash.com/premium_photo-1673439304183-8840bd0dc1bf?w=1000&auto=format&fit=crop&q=60&ixlib=rb-4.1.0&ixid=NHwxMjA3fDA%3D', 'https://www.youtube.com/watch?v=vcfNpDtVqOw&pp=ygUQTWFyZ2hlcml0YSBQaXp6YQ%3D%3D', TRUE, 2.99, '2025-12-14 17:45:00', '2025-12-14 17:45:00', '2025-12-14 17:45:00', 6),
  (16, 'Provencal Ratatouille', '2 zucchinis\n1 eggplants\n2 bell peppers\n4 tomatoes\n1 onions\n2 garlic cloves\n3 tbsp olive oil\nSalt (to taste)\nBlack pepper (to taste)', 'Dice all the vegetables into similar-sized cubes.\nFry the onion and garlic in the olive oil.\nAdd the eggplant, peppers and zucchini and cook for 10 minutes.\nAdd the tomatoes, season, cover and simmer for 40 minutes.\nServe hot, warm or cold.', 75, 'Plat', 'https://plus.unsplash.com/premium_photo-1713635953474-b74990274152?q=80&w=1184&auto=format&fit=crop&ixlib=rb-4.1.0&ixid=NHwxMjA3fDA%3D', 'https://www.youtube.com/watch?v=1cHP_-AMquQ&pp=ygUVUHJvdmVuY2FsIFJhdGF0b3VpbGxl', TRUE, NULL, '2025-08-03 14:20:00', '2025-08-03 14:20:00', '2025-08-03 14:20:00', 9),
  (17, 'Lemon Garlic Roast Potatoes', '800 g potatoes\n3 tbsp olive oil\n4 garlic cloves\n1 lemons\nSalt (to taste)\nBlack pepper (to taste)', 'Preheat the oven to 200°C (400°F).\nCut the potatoes into wedges and toss them with the olive oil, salt and pepper.\nRoast for 35 minutes, turning once.\nAdd the crushed garlic and the lemon juice and roast for 10 more minutes.', 50, 'Plat', 'https://plus.unsplash.com/premium_photo-1695224545124-3ef48642ec92?w=600&auto=format&fit=crop&q=60&ixlib=rb-4.1.0&ixid=NHwxMjA3fDA%3D', 'https://www.youtube.com/watch?v=argKpeiKFfo&t=143s&pp=ygUbbGVtb24gZ2FybGljIHJvYXN0IHBvdGF0b2Vz', TRUE, NULL, '2026-03-08 16:05:00', '2026-03-08 16:05:00', '2026-03-08 16:05:00', 5),
  (18, 'Greek Salad', '4 tomatoes\n1 cucumbers\n1 onions\n150 g feta\n80 g black olives\n3 tbsp olive oil\nSalt (to taste)', 'Cut the tomatoes and the cucumber into chunks and slice the onion.\nCombine them in a bowl with the olives.\nTop with the feta in a large piece or crumbled.\nDrizzle with olive oil and season with salt.', 15, 'Entrée', 'https://images.unsplash.com/photo-1505253716362-afaea1d3d1af?w=1000&auto=format&fit=crop&q=60&ixlib=rb-4.1.0&ixid=NHwxMjA3fDA%3D', 'https://www.youtube.com/watch?v=dDhOpHcAJGo&pp=ygULR3JlZWsgU2FsYWTSBwkJyAcBhyohjO8%3D', TRUE, NULL, '2025-10-12 11:55:00', '2025-10-12 11:55:00', '2025-10-12 11:55:00', 1),
  (19, 'Fresh Guacamole', '3 avocados\n1 limes\n1 tomatoes\n1 onions\nSalt (to taste)', 'Mash the avocados with a fork, leaving some small chunks.\nFinely dice the onion and the tomato.\nMix everything with the lime juice and salt.\nServe immediately with tortilla chips.', 10, 'Plat', 'https://images.unsplash.com/photo-1680992071073-cb1696ba8d3e?w=1000&auto=format&fit=crop&q=60&ixlib=rb-4.1.0&ixid=NHwxMjA3fDA%3D', 'https://www.youtube.com/watch?v=tHVzFLtvbGQ&pp=ygUPRnJlc2ggR3VhY2Ftb2xl', TRUE, NULL, '2026-09-13 15:35:00', '2026-09-13 15:35:00', '2026-09-13 15:35:00', 11),
  (20, 'Moist Banana Bread', '3 bananas\n250 g flour\n150 g sugar\n100 g butter\n2 eggs\n2 tsp baking powder\nSalt (to taste)', 'Preheat the oven to 175°C (350°F) and grease a loaf pan.\nMash the very ripe bananas and mix them with the melted butter, sugar and eggs.\nFold in the flour, baking powder and a pinch of salt.\nPour into the pan and bake for 50 to 55 minutes.\nLet cool before slicing.', 70, 'Dessert', 'https://images.unsplash.com/photo-1569762404472-026308ba6b64?q=80&w=687&auto=format&fit=crop&ixlib=rb-4.1.0&ixid=NHwxMjA3fDA%3D', 'https://www.youtube.com/watch?v=qUmDpPfY_h0&pp=ygUSTW9pc3QgQmFuYW5hIEJyZWFk', TRUE, NULL, '2026-07-05 09:05:00', '2026-07-05 09:05:00', '2026-07-05 09:05:00', 10),
  (21, 'Cinnamon Apple Crumble', '5 apples\n150 g flour\n100 g butter\n100 g sugar\n1 tsp cinnamon', 'Peel and slice the apples, then arrange them in a baking dish with the cinnamon.\nRub the cold butter into the flour and sugar until you get coarse crumbs.\nSpread the crumble over the apples.\nBake for 35 minutes at 180°C (350°F) until golden.', 50, 'Dessert', 'https://images.unsplash.com/photo-1506127946181-abb01a32593c?q=80&w=1170&auto=format&fit=crop&ixlib=rb-4.1.0&ixid=NHwxMjA3fDA%3D', 'https://www.youtube.com/watch?v=n-iaYRd9Arw&pp=ygUWQ2lubmFtb24gQXBwbGUgQ3J1bWJsZQ%3D%3D', TRUE, NULL, '2025-10-19 16:00:00', '2025-10-19 16:00:00', '2025-10-19 16:00:00', 10),
  (22, 'Caprese Salad', '3 tomatoes\n125 g mozzarella\n10 g fresh basil\n2 tbsp olive oil\nSalt (to taste)', 'Slice the tomatoes and the mozzarella.\nAlternate the slices on a plate and add the basil leaves.\nDrizzle with olive oil and sprinkle with salt.', 10, 'Entrée', 'https://images.unsplash.com/photo-1769458313937-b5ad8f84942e?w=1000&auto=format&fit=crop&q=60&ixlib=rb-4.1.0&ixid=NHwxMjA3fDA%3D', 'https://www.youtube.com/watch?v=gOcfUgd4ekA&pp=ygUNQ2FwcmVzZSBTYWxhZA%3D%3D', TRUE, NULL, '2026-06-27 10:25:00', '2026-06-27 10:25:00', '2026-06-27 10:25:00', 6),
  (23, 'Creamy Mushroom Risotto', '300 g arborio rice\n250 g mushrooms\n1 onions\n30 g butter\n1000 ml vegetable broth\n60 g parmesan\nBlack pepper (to taste)', 'Keep the vegetable broth hot in a saucepan.\nCook the sliced mushrooms in a pan until golden, then set them aside.\nSoften the chopped onion in the butter, add the rice and stir for 2 minutes.\nAdd the broth one ladle at a time, stirring, until the rice is creamy (about 18 minutes).\nStir in the mushrooms, the grated parmesan and black pepper.', 45, 'Plat', 'https://images.unsplash.com/photo-1609770424775-39ec362f2d94?q=80&w=765&auto=format&fit=crop&ixlib=rb-4.1.0&ixid=NHwxMjA3fDA%3D', 'https://www.youtube.com/watch?v=NKtR3KpS83w&pp=ygUXQ3JlYW15IE11c2hyb29tIFJpc290dG8%3D', TRUE, 2.99, '2026-01-18 18:00:00', '2026-01-18 18:00:00', '2026-01-18 18:00:00', 6),
  (24, 'Hearty Lentil Soup', '250 g lentils\n2 carrots\n1 onions\n2 garlic cloves\n200 g canned tomatoes\n1000 ml vegetable broth\n2 tbsp olive oil\n1 tsp cumin\nSalt (to taste)', 'Soften the chopped onion, carrots and garlic in the olive oil.\nAdd the cumin, the rinsed lentils, the tomatoes and the broth.\nSimmer for 25 to 30 minutes until the lentils are tender.\nSeason with salt and serve hot.', 40, 'Plat', 'https://plus.unsplash.com/premium_photo-1712678665743-15e3833da37e?w=1000&auto=format&fit=crop&q=60&ixlib=rb-4.1.0&ixid=NHwxMjA3fDA%3D', 'https://www.youtube.com/watch?v=mdT3tFEug00&pp=ygUSSGVhcnR5IExlbnRpbCBTb3Vw', TRUE, NULL, '2026-04-12 12:30:00', '2026-04-12 12:30:00', '2026-04-12 12:30:00', 7),
  (25, 'Tuna Mayo Sandwich', '160 g canned tuna\n2 tbsp mayonnaise\n4 bread slices\n2 lettuce leaves', 'Drain the tuna and mix it with the mayonnaise.\nToast the bread slices.\nSpread the tuna mixture on two slices, add the lettuce and close the sandwiches.', 10, 'Plat', 'https://images.unsplash.com/photo-1754652327590-634bfebc7cf0?w=1000&auto=format&fit=crop&q=60&ixlib=rb-4.1.0&ixid=NHwxMjA3fDA%3D', 'https://www.youtube.com/watch?v=JA-930RFSSE&pp=ygUSVHVuYSBNYXlvIFNhbmR3aWNo', TRUE, NULL, '2026-05-17 12:15:00', '2026-05-17 12:15:00', '2026-05-17 12:15:00', 8),
  (26, 'Cinnamon French Toast', '4 bread slices\n2 eggs\n100 ml milk\n1 tbsp sugar\n20 g butter\n1 tsp cinnamon', 'Whisk the eggs with the milk, sugar and cinnamon in a shallow dish.\nSoak each bread slice for 30 seconds on each side.\nFry the slices in the butter until golden on both sides.', 15, 'Plat', 'https://images.unsplash.com/photo-1595044643502-616eeebbdff3?q=80&w=1470&auto=format&fit=crop&ixlib=rb-4.1.0&ixid=NHwxMjA3fDA%3D', 'https://www.youtube.com/watch?v=njuQDii24Dk&pp=ygUVQ2lubmFtb24gRnJlbmNoIFRvYXN0', TRUE, NULL, '2026-10-18 08:20:00', '2026-10-18 08:20:00', '2026-10-18 08:20:00', 10);
