INSERT INTO `RecipeRequests` (`id`, `requesterId`, `targetChefId`, `title`, `description`, `dietaryNotes`, `offeredAmount`, `status`, `fulfilledRecipeId`, `createdAt`, `updatedAt`) VALUES
  (1, 11, 9, 'Vegan Bouillabaisse', 'Is it possible to make a plant-based bouillabaisse that still tastes of the sea? Seaweed and fennel welcome.', 'Vegan', 25.0, 'cancelled', NULL, '2026-03-05 12:00:00', '2026-03-09 10:30:00'),
  (2, 15, 10, 'Beginner-Friendly Banana Bread', 'I am new to baking and my banana bread always sinks in the middle. Could you share a foolproof recipe with a video?', NULL, 20.0, 'completed', 20, '2026-06-10 18:20:00', '2026-07-06 09:00:00'),
  (3, 16, 10, 'Weekend French Toast for Brunch', 'Looking for a rich cinnamon French toast I can serve at weekend brunch with friends.', 'Vegetarian', 10.0, 'fulfilled', 26, '2026-10-02 10:00:00', '2026-10-18 20:00:00'),
  (4, 12, 6, 'Gluten-Free Fresh Tagliatelle', 'Could you create a detailed recipe + video for homemade gluten-free tagliatelle that holds its texture?', 'Gluten-free', 15.0, 'accepted', NULL, '2026-10-20 13:55:00', '2026-10-21 09:10:00'),
  (5, 8, NULL, 'Authentic West African Thieboudienne', 'Looking for a step-by-step weekend recipe for traditional red Thieboudienne with stuffed fish.', NULL, 20.0, 'open', NULL, '2026-11-12 16:45:00', '2026-11-12 16:45:00'),
  (6, 11, 6, 'Mushroom and Truffle Ravioli', 'Could you create a vegetarian ravioli filled with mushrooms and a hint of truffle, with a video of the folding?', 'Vegetarian', 25.0, 'accepted', NULL, '2026-11-03 18:30:00', '2026-11-04 09:00:00'),
  (7, 16, 8, 'Smoky Beef Short Ribs on the Braai', 'I want a slow braai recipe for beef short ribs for a family weekend, with the marinade explained step by step.', NULL, 20.0, 'open', NULL, '2026-11-18 17:10:00', '2026-11-18 17:10:00'),
  (8, 9, 10, 'Salted Caramel Tart for Beginners', 'A reliable salted caramel tart that does not crack, with a short video for the caramel stage.', NULL, 15.0, 'accepted', NULL, '2026-11-05 10:15:00', '2026-11-06 08:50:00'),
  (9, 15, 7, 'Easy Chicken Yassa for One', 'Could you adapt the chicken yassa for a single portion with less marinating time?', NULL, 10.0, 'cancelled', NULL, '2026-09-20 19:00:00', '2026-09-22 10:30:00'),
  (10, 12, NULL, 'Vegetarian West African Stew', 'Looking for a hearty vegetarian stew inspired by West African flavours, medium spicy.', 'Vegetarian', 18.0, 'open', NULL, '2026-11-21 20:00:00', '2026-11-21 20:00:00');
