INSERT INTO `ChatMessages` (`id`, `roomId`, `senderId`, `content`, `isDeleted`, `createdAt`) VALUES
  (1, 1, 1, 'Welcome to the Ef''Recipe Lounge! Say hi, tell us what you are cooking and please be kind to each other.', FALSE, '2025-03-03 09:40:00'),
  (2, 2, 1, 'Welcome to the team, Cyp. This channel is for moderation questions only.', FALSE, '2025-03-17 10:45:00'),
  (3, 1, 5, 'Hello everyone! Lucas here, pastry from Lyon. My first Tarte Tatin video is coming this month.', FALSE, '2025-04-02 18:05:00'),
  (4, 1, 5, 'The Tarte Tatin is live! Tip: wait for a deep amber caramel before adding the apples.', FALSE, '2025-04-26 19:30:00'),
  (5, 1, 6, 'Ciao from Bologna, Lucas! I am no pastry guy but I am trying it this weekend.', FALSE, '2025-04-27 08:12:00'),
  (6, 1, 6, 'Authentic carbonara is online. Rules: guanciale, pecorino, eggs, pepper. That is it.', FALSE, '2025-05-11 20:15:00'),
  (7, 1, 5, 'Not a drop of cream. I approve.', FALSE, '2025-05-11 20:40:00'),
  (8, 2, 1, 'Welcome Lili! Billing tickets are all yours.', FALSE, '2025-06-09 14:30:00'),
  (9, 1, 8, 'Hey from Austin! Brisket is my thing, but I will start with burgers.', FALSE, '2025-06-14 19:50:00'),
  (10, 1, 7, 'Chicken Yassa is up! Marinate the onions for at least two hours, trust me.', FALSE, '2025-06-15 10:20:00'),
  (11, 1, 9, 'Bonjour! Marseille here. Ratatouille season is coming.', FALSE, '2025-07-09 11:05:00'),
  (12, 1, 10, 'Hi all! I am Julie, baking and desserts. Happy to be here.', FALSE, '2025-08-12 16:00:00'),
  (13, 2, 1, 'Welcome rayoogo! Bug reports and playback issues are your area.', FALSE, '2025-09-15 12:10:00'),
  (14, 1, 11, 'Hello from Montreal! Plant-forward cooking is my thing.', FALSE, '2025-09-23 10:10:00'),
  (15, 3, 11, 'Hi Lucas, I loved your Tarte Tatin video! I unlocked it last week.', FALSE, '2025-10-05 18:10:00'),
  (16, 3, 5, 'Thank you Nina! Next time try pears instead of apples.', FALSE, '2025-10-05 19:25:00'),
  (17, 3, 11, 'Great idea, I will film my attempt if it works!', FALSE, '2025-10-06 07:50:00'),
  (18, 1, 12, 'Hi everyone, I am Sophie, a home cook testing recipes from all of you.', FALSE, '2025-10-30 20:30:00'),
  (19, 4, 10, 'Welcome to the pastry club! Share your bakes and your failures here.', FALSE, '2025-11-02 18:05:00'),
  (20, 4, 5, 'Great idea Julie. Who wants a Tarte Tatin masterclass?', FALSE, '2025-11-02 18:20:00'),
  (21, 4, 12, 'Count me in! My caramel always burns.', FALSE, '2025-11-03 09:00:00'),
  (22, 4, 5, 'Medium heat, do not stir, just swirl the pan.', FALSE, '2025-11-03 09:30:00'),
  (23, 1, 13, 'Greetings from Cape Town! Braai master in the making.', FALSE, '2025-12-04 18:40:00'),
  (24, 1, 1, 'Happy New Year, chefs! Thank you for filling this kitchen with so many great recipes this year.', FALSE, '2025-12-31 20:00:00'),
  (25, 1, 14, 'Hi all, I love kitchen gadgets. Any air fryer fans here?', FALSE, '2026-02-14 13:50:00'),
  (26, 1, 14, 'BEST KITCHEN GADGETS AT CRAZY PRICES!! visit cheapest-kitchen-deals.example now and save big', TRUE, '2026-03-01 20:50:00'),
  (27, 1, 2, 'Reminder: no promotional links in the lounge. Messages with ads are removed by the moderators.', FALSE, '2026-03-02 08:10:00'),
  (28, 1, 14, 'Last chance: 70% off all blenders on cheapest-kitchen-deals.example, click now!!!', TRUE, '2026-03-04 09:10:00'),
  (29, 2, 2, 'Banned Kyle after the second spam message. Logging it.', FALSE, '2026-03-04 09:40:00'),
  (30, 1, 2, 'The spam account has been removed from the community. Thanks for the reports, Tom and Pierre!', FALSE, '2026-03-04 10:00:00'),
  (31, 2, 3, 'Warning issued to Thando for the insulting review on the yassa.', FALSE, '2026-03-22 14:10:00'),
  (32, 2, 1, 'Thando''s report privilege is removed after three unfounded copyright reports. She can appeal through a ticket.', FALSE, '2026-05-06 11:00:00'),
  (33, 4, 15, 'Hi! I am new here. My first banana bread sank in the middle...', FALSE, '2026-05-08 15:10:00'),
  (34, 4, 10, 'Classic! Probably the oven door opened too early. Let us fix it together.', FALSE, '2026-05-08 15:30:00'),
  (35, 1, 8, 'New recipe: Tuna Mayo Sandwich. The easiest lunch ever.', FALSE, '2026-05-17 12:30:00'),
  (36, 1, 15, 'I am a total beginner. Is it OK if I try that one first?', FALSE, '2026-05-17 12:50:00'),
  (37, 1, 8, 'Absolutely Zoe, that is exactly what it is made for.', FALSE, '2026-05-17 13:05:00'),
  (38, 2, 3, 'She opened a ticket as expected. Marking it admin only.', FALSE, '2026-05-20 16:30:00'),
  (39, 4, 15, 'Julie, I just sent you a paid request for a foolproof banana bread.', FALSE, '2026-06-10 18:25:00'),
  (40, 4, 10, 'Got it Zoe, I will film it soon.', FALSE, '2026-06-11 09:00:00'),
  (41, 5, 8, 'Welcome to the grill room. Burgers, ribs, braai, anything with fire.', FALSE, '2026-06-22 10:05:00'),
  (42, 5, 16, 'Finally, a braai club!', FALSE, '2026-06-22 10:20:00'),
  (43, 5, 13, 'Boerewors or burgers? Go.', FALSE, '2026-06-23 18:30:00'),
  (44, 5, 16, 'Boerewors, always.', FALSE, '2026-06-23 18:41:00'),
  (45, 5, 9, 'Grilled sardines beat both, but I respect the debate.', FALSE, '2026-06-23 19:02:00'),
  (46, 1, 6, 'Caprese is live. Five ingredients, zero excuses.', FALSE, '2026-06-27 17:00:00'),
  (47, 1, 10, 'Banana bread is up! Thank you Zoe for the request.', FALSE, '2026-07-05 21:00:00'),
  (48, 4, 15, 'Making it tonight, fingers crossed!', FALSE, '2026-07-05 21:10:00'),
  (49, 5, 16, 'Cooked Tom''s cheeseburger on Saturday. Huge hit with the whole family.', FALSE, '2026-09-20 17:15:00'),
  (50, 5, 8, 'Love to hear it, Mpho!', FALSE, '2026-09-20 17:40:00'),
  (51, 1, 10, 'French toast recipe is live, made for Mpho''s request.', FALSE, '2026-10-18 20:30:00'),
  (52, 6, 12, 'Hi Marco! I just submitted a paid request for gluten-free tagliatelle.', FALSE, '2026-10-20 14:06:00'),
  (53, 6, 6, 'Ciao Sophie! Accepted. I will film the dough kneading process this weekend.', FALSE, '2026-10-21 09:15:00'),
  (54, 6, 12, 'Wonderful, thank you so much!', FALSE, '2026-10-21 10:02:00'),
  (55, 6, 6, 'Filming went well, I am editing now. It should be ready next week.', FALSE, '2026-11-08 18:20:00'),
  (56, 6, 12, 'No rush, take your time!', FALSE, '2026-11-08 18:45:00'),
