  (73, 1, 1, 'Thank you Nina! It is a classic for a reason.', FALSE, '2025-10-12 13:00:00'),
  (74, 8, 5, 'Marco, could you read my draft for Pear Tarte Tatin? I am not sure the steps are clear.', FALSE, '2025-11-01 08:41:00'),
