  (121, 13, 12, 'Will do, thanks!', FALSE, '2026-03-15 14:54:00'),
  (122, 14, 9, 'Hi Marco! I finally cooked your Spaghetti Bolognese last night and I had to tell you.', FALSE, '2026-03-30 20:08:00'),
  (123, 14, 6, 'Hi Pierre! That makes my day. How did it turn out?', FALSE, '2026-03-31 07:36:00'),
