  (162, 19, 13, 'Hello Lili, I have a question about my Gourmet Plus subscription.', FALSE, '2026-06-26 09:55:00'),
  (163, 19, 3, 'Hi Thando! Happy to help. What would you like to know?', FALSE, '2026-06-26 11:19:00'),
  (164, 19, 13, 'When exactly is the next payment taken, and can I cancel at any time?', FALSE, '2026-06-26 11:29:00'),
  (165, 19, 3, 'You are billed monthly (R30.00) on the day you subscribed. You can cancel from your profile at any time and keep access until the end of the paid period.', FALSE, '2026-06-26 11:41:00'),
  (166, 19, 13, 'That is clear, thanks. And if a payment fails?', FALSE, '2026-06-26 11:57:00'),
