  (224, 25, 11, 'Welcome to the Plant-Based & Fresh corner! Vegetables first, always.', FALSE, '2026-08-02 10:03:00'),
  (225, 25, 7, 'Thank you Nina! West African cooking is full of vegetable stews, I will share some.', FALSE, '2026-08-02 10:23:00'),
