  (227, 25, 7, 'Maafe with sweet potato, you will love it.', FALSE, '2026-08-02 10:46:00'),
  (228, 25, 12, 'Is there a vegetarian dish for a crowd? Cooking for eight on Sunday.', FALSE, '2026-08-02 15:46:00'),
  (229, 25, 11, 'Ratatouille scales perfectly and is better the next day.', FALSE, '2026-08-02 15:58:00'),
  (230, 25, 16, 'My braai friends would happily eat grilled vegetables if there is halloumi involved.', FALSE, '2026-08-02 16:58:00'),
  (231, 25, 11, 'Grill the veg with olive oil and finish with halloumi and lemon. Done.', FALSE, '2026-08-02 17:08:00'),
  (232, 25, 15, 'I tried the stir-fry and the broccoli went soft...', FALSE, '2026-08-03 18:08:00'),
  (233, 25, 11, 'High heat, small batches, and do not cover the wok. Crunch is the goal.', FALSE, '2026-08-03 18:26:00'),
