  (356, 36, 6, 'Please do. Good luck!', FALSE, '2026-10-30 08:19:00'),
  (357, 41, 16, 'Hello Pierre, I wanted to try your Garlic Butter Shrimp but I cannot find one of the ingredients near me.', FALSE, '2026-11-03 16:18:00'),
  (358, 41, 9, 'Hi Mpho! Which one is missing?', FALSE, '2026-11-03 16:40:00'),
  (359, 41, 16, 'Nothing exotic, but the shop only has a different version of it.', FALSE, '2026-11-03 16:45:00'),
  (360, 41, 9, 'Then use what you have. The recipe is forgiving, just adjust the quantity by taste and add a little at a time.', FALSE, '2026-11-03 22:04:00'),
  (361, 41, 16, 'That is reassuring, I was afraid to ruin it.', FALSE, '2026-11-03 22:17:00'),
  (362, 41, 9, 'You will not. Cooking is mostly tasting and adjusting.', FALSE, '2026-11-04 07:41:00'),
