INSERT INTO `Reports` (`id`, `reporterId`, `targetType`, `targetId`, `reason`, `details`, `status`, `reviewedBy`, `moderatorNote`, `targetOwnerId`, `targetLabel`, `action`, `decisionMessage`, `createdAt`, `updatedAt`) VALUES
  (1, 6, 'review', 27, 'other', 'Testing the report button. This feels a bit negative to me.', 'dismissed', 3, 'Constructive taste feedback, within community guidelines.', 12, 'Review on a recipe: Good, but a little too sweet for me.', 'none', NULL, '2025-11-09 11:20:00', '2025-11-09 15:40:00'),
  (2, 8, 'chat_message', 26, 'spam', 'Advertising link posted in the lounge.', 'action_taken', 2, 'First offence: warning sent and message removed.', 14, 'Chat message by Kyle_Jacobs: BEST KITCHEN GADGETS AT CRAZY PRICES!!', 'warning', 'Promotional links are not allowed in the community chat. Please read the guidelines before posting again.', '2026-03-01 21:05:00', '2026-03-02 08:06:00'),
  (3, 9, 'chat_message', 28, 'spam', 'Same account, same spam, after the warning.', 'action_taken', 2, 'Second spam message after a warning: account banned.', 14, 'Chat message by Kyle_Jacobs: Last chance: 70% off all blenders...', 'user_banned', 'Your account was banned for repeated promotional spam. You can appeal through a support ticket.', '2026-03-04 09:30:00', '2026-03-04 09:52:00'),
  (4, 7, 'review', 31, 'harassment', 'This review insults me personally, not the recipe.', 'action_taken', 3, 'Personal attack in a review. Official warning issued.', 13, 'Review on a recipe: Way too spicy and nothing like the real thing...', 'warning', 'Criticism of a recipe is welcome, personal insults are not. Please keep reviews respectful.', '2026-03-22 09:15:00', '2026-03-22 14:05:00'),
  (5, 13, 'recipe', 3, 'copyright', 'This looks copied from a restaurant menu.', 'dismissed', 2, 'No evidence. The recipe and its video show original authorship.', 7, 'Recipe: Senegalese Chicken Yassa', 'none', NULL, '2026-04-28 20:10:00', '2026-04-29 09:00:00'),
  (6, 13, 'recipe', 13, 'copyright', 'Also copied from somewhere.', 'dismissed', 4, 'No source provided. Dismissed.', 7, 'Recipe: Creamy Chicken Curry', 'none', NULL, '2026-05-02 19:40:00', '2026-05-03 08:30:00'),
  (7, 13, 'recipe', 24, 'copyright', 'Copied again.', 'dismissed', 1, 'Third unfounded report in nine days. Reporting privilege removed.', 7, 'Recipe: Hearty Lentil Soup', 'none', 'Your reports were reviewed and dismissed three times without evidence. Your ability to report content has been removed.', '2026-05-06 10:20:00', '2026-05-06 11:02:00'),
  (8, 12, 'review', 34, 'spam', 'Review used to advertise an external shop.', 'pending', NULL, NULL, 16, 'Review on a recipe: Great patties. Mine went on the braai... more braai tips and gear at my-braai-box.example!', NULL, NULL, '2026-11-24 19:30:00', '2026-11-24 19:30:00'),
  (9, 12, 'recipe', 19, 'other', 'The video link seems to be the wrong recipe.', 'dismissed', 4, 'Checked: the video matches the recipe. Closed.', 11, 'Recipe: Fresh Guacamole', 'none', NULL, '2026-09-20 09:10:00', '2026-09-20 14:30:00'),
  (10, 16, 'recipe', 25, 'inappropriate_content', 'The photo looks like it is from another website.', 'dismissed', 3, 'Author confirmed the photo is their own. Dismissed.', 8, 'Recipe: Tuna Mayo Sandwich', 'none', NULL, '2026-06-01 13:00:00', '2026-06-02 08:45:00'),
  (11, 5, 'review', 41, 'harassment', 'This review feels unfair and unkind.', 'dismissed', 2, 'Honest feedback about the recipe, no guideline violation.', 6, 'Review on a recipe: It was fine. It needed more flavour for my taste. Maybe I will try ...', 'none', NULL, '2025-12-30 13:01:00', '2025-12-30 18:01:00'),
  (12, 5, 'recipe', 18, 'copyright', 'This looks like a classic menu copy.', 'dismissed', 2, 'Classic recipe, no copied text found.', 1, 'Recipe: Greek Salad', 'none', NULL, '2026-07-11 16:20:00', '2026-07-12 09:00:00'),
  (13, 15, 'user', 16, 'spam', 'This user posted the same promo link in a review.', 'pending', NULL, NULL, 16, 'User: Mpho_Khumalo', NULL, NULL, '2026-11-24 22:00:00', '2026-11-24 22:00:00'),
  (14, 6, 'review', 34, 'spam', 'Same external promo link as the other review.', 'pending', NULL, NULL, 16, 'Review on a recipe: Great patties. Mine went on the braai... more braai tips and gear at my-braai-box.example!', NULL, NULL, '2026-11-25 08:10:00', '2026-11-25 08:10:00'),
  (15, 11, 'review', 90, 'other', 'I think this rating is too harsh for what is a simple recipe.', 'pending', NULL, NULL, 16, 'Review on a recipe: It was fine. I found it a bit bland and added more seasoning.', NULL, NULL, '2026-11-22 09:00:00', '2026-11-22 09:00:00'),
  (16, 9, 'recipe', 23, 'other', 'Missing step: when to add the mushrooms back into the risotto.', 'reviewed', 3, 'Author notified and the instructions were clarified.', 6, 'Recipe: Creamy Mushroom Risotto', 'none', NULL, '2026-04-03 18:15:00', '2026-04-04 10:00:00');
INSERT INTO `ModContactTickets` (`id`, `userId`, `assignedModId`, `subject`, `category`, `message`, `status`, `adminReply`, `createdAt`, `updatedAt`, `adminOnly`) VALUES
  (1, 10, 3, 'Question about creator video payouts', 'billing', 'Hello moderators, how do I set up my payout details for my premium video recipes?', 'resolved', 'Hi Julie! You can configure your creator payout method directly in your Profile Settings tab.', '2025-11-08 14:00:00', '2025-11-08 16:20:00', FALSE),
  (2, 14, 2, 'Appeal: my account was banned', 'ban_appeal', 'I only wanted to share useful deals. Please unban me, I will not post links again.', 'closed', 'We reviewed the case again: two spam messages in three days, one after an official warning. The ban stays in place.', '2026-03-06 10:15:00', '2026-03-12 11:00:00', FALSE),
  (3, 12, 3, 'Are file downloads included in Gourmet Plus?', 'general', 'Hi! As a subscriber, can I also download recipe files for free?', 'resolved', 'Hi Sophie! Gourmet Plus unlocks all the videos, but file downloads are billed separately at R5 per file.', '2026-04-14 12:00:00', '2026-04-14 12:40:00', FALSE),
  (4, 13, 1, 'Please restore my reporting access', 'other', 'I reported those recipes because I really thought they were copies. I understand now that I was wrong. Can I get the report button back?', 'in_progress', 'The restriction stays until at least 6 February 2027. We will review your account then if your behaviour stays respectful.', '2026-05-20 09:45:00', '2026-11-10 10:30:00', TRUE),
  (5, 9, 4, 'Recipe video does not load', 'bug', 'The video of the Traditional Tarte Tatin shows a black screen on my phone.', 'resolved', 'Fixed! It was a cache problem on our side. Please refresh the page and it should play.', '2026-09-20 18:20:00', '2026-09-21 10:00:00', FALSE),
  (6, 15, NULL, 'Payment failed on my subscription', 'billing', 'My card was declined on 10 November although the money is there. My subscription now says past due. What should I do?', 'open', NULL, '2026-11-12 08:30:00', '2026-11-12 08:30:00', FALSE),
  (7, 5, 4, 'My video thumbnail is not updating', 'bug', 'I replaced the cover image of my Tarte Tatin but the old thumbnail still shows in the lists.', 'resolved', 'Fixed! The old image was cached. It now updates when you save the recipe.', '2026-08-12 10:00:00', '2026-08-12 15:30:00', FALSE),
  (8, 9, 3, 'Where can I find my invoices?', 'billing', 'I would like a receipt for my previous subscription payments for my accounting.', 'resolved', 'You can download them from your profile under Payments. If one is missing, tell us the date.', '2026-05-19 09:00:00', '2026-05-19 11:10:00', FALSE),
  (9, 16, 2, 'Can I promote my braai shop here?', 'general', 'I run a small braai accessories shop. Can I post my links in the lounge and in reviews?', 'closed', 'Promotion in chat and reviews is not allowed. Partnerships and ads are handled by the platform team.', '2026-10-05 08:45:00', '2026-10-06 09:00:00', FALSE),
  (10, 11, 2, 'Can I change my username?', 'other', 'Is it possible to change my username? I would like to use my full name.', 'resolved', 'Username changes are not supported yet, but we noted your request for a future update.', '2026-07-01 16:00:00', '2026-07-02 09:20:00', FALSE),
  (11, 7, 3, 'When is my next renewal?', 'billing', 'I subscribed in February. Could you confirm the date of my next renewal?', 'in_progress', NULL, '2026-11-18 10:30:00', '2026-11-19 09:15:00', FALSE),
  (12, 12, NULL, 'Status of my paid request', 'general', 'My gluten-free tagliatelle request was accepted in October. Is there an expected delivery date?', 'open', NULL, '2026-11-23 19:45:00', '2026-11-23 19:45:00', FALSE);
INSERT INTO `ModTicketMessages` (`id`, `ticketId`, `senderId`, `isStaff`, `readByUser`, `content`, `createdAt`) VALUES
  (1, 1, 3, 1, 1, 'Hi Julie! You can configure your creator payout method directly in your Profile Settings tab.', '2025-11-08 16:20:00'),
  (2, 1, 10, 0, 1, 'Found it, thank you Lili!', '2025-11-08 17:05:00'),
  (3, 2, 2, 1, 1, 'We reviewed your messages: two spam links in three days after a warning. Can you confirm you understand the community rules?', '2026-03-08 09:30:00'),
  (4, 2, 14, 0, 1, 'I understand the rules, but I think the ban is harsh.', '2026-03-09 18:00:00'),
  (5, 2, 2, 1, 1, 'We reviewed the case again: two spam messages in three days, one after an official warning. The ban stays in place.', '2026-03-12 11:00:00'),
  (6, 3, 3, 1, 1, 'Hi Sophie! Gourmet Plus unlocks all the videos, but file downloads are billed separately at R5 per file.', '2026-04-14 12:40:00'),
  (7, 4, 1, 1, 1, 'We received your ticket and are reviewing your report history. We will come back to you.', '2026-05-21 08:50:00'),
  (8, 4, 13, 0, 1, 'Any update please? I really have not reported anything since.', '2026-06-02 12:00:00'),
  (9, 5, 4, 1, 1, 'Thanks for the report Pierre. Which browser are you using?', '2026-09-20 19:00:00'),
  (10, 5, 9, 0, 1, 'Chrome on Android.', '2026-09-20 19:30:00'),
  (11, 5, 4, 1, 1, 'Fixed! It was a cache problem on our side. Please refresh the page and it should play.', '2026-09-21 10:00:00'),
  (12, 4, 1, 1, 0, 'The restriction stays until at least 6 February 2027. We will review your account then if your behaviour stays respectful.', '2026-11-10 10:30:00'),
  (13, 7, 4, 1, 1, 'Thanks Lucas, I can reproduce it. Can you tell me which image format you uploaded?', '2026-08-12 11:00:00'),
  (14, 7, 5, 0, 1, 'A JPG, around 2 MB.', '2026-08-12 11:40:00'),
  (15, 7, 4, 1, 1, 'Fixed! The old image was cached. It now updates when you save the recipe.', '2026-08-12 15:30:00'),
  (16, 8, 3, 1, 1, 'Hi Pierre! You can download them from your profile under Payments. If one is missing, tell us the date.', '2026-05-19 11:10:00'),
  (17, 8, 9, 0, 1, 'Found them, thank you Lili!', '2026-05-19 12:00:00'),
  (18, 9, 2, 1, 1, 'Hi Mpho, thanks for asking first. Links promoting a shop are not allowed in the lounge or in reviews.', '2026-10-05 10:00:00'),
  (19, 9, 16, 0, 1, 'Understood, thanks for the clear answer.', '2026-10-05 11:30:00'),
  (20, 9, 2, 1, 1, 'Promotion in chat and reviews is not allowed. Partnerships and ads are handled by the platform team.', '2026-10-06 09:00:00'),
  (21, 10, 2, 1, 1, 'Username changes are not supported yet, but we noted your request for a future update.', '2026-07-02 09:20:00'),
  (22, 11, 3, 1, 0, 'Hi Awa! Your subscription renews on the 3rd of each month. I am double-checking your last invoice and will confirm.', '2026-11-19 09:15:00');
